// Stack-level symptom: the landing band and the ops map controls should each sit at their own layer, with the band above the map.
await page.goto('/login');
const band = page.getByRole('banner');
await expect(band).toBeVisible();
await expect(band).toHaveCSS('position', 'fixed');

await page.goto('/ops/radar');
const zoomIn = page.getByRole('button', { name: 'Zoom in' });
await expect(zoomIn).toBeVisible();
await expect(zoomIn).toBeEnabled();
// The map controls must not be pushed above the landing band layer.
await expect(zoomIn).not.toHaveCSS('z-index', '9999');
```

